select case when quantity >= 8 then 'high' when quantity >= 4 then 'mid' else 'low' end as quantity_bucket, sum(quantity) as total_quantity, sum(sum(quantity)) over (order by case when quantity >= 8 then 'high' when quantity >= 4 then 'mid' else 'low' end) as cumulative_quantity from order_items where product_id is null group by case when quantity >= 8 then 'high' when quantity >= 4 then 'mid' else 'low' end order by cumulative_quantity
